Method.Implementation:
Set tStatus = $$$OK
Try {
	If '$IsObject($get(pBatch)) Set tStatus = $$$ERROR($$$ObjectInstanceRequired) Quit
	If '$IsObject(pIOStream) {
		Set tFilename = pIOStream
		Set pIOStream = ##class(%IO.FileStream).%New()
		Do pIOStream.Open(tFilename,"WAE",,"UTF-8",.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	Set tStatus = ##class(IHC.ITF.BILLING.DStruc.ARMRefundToIDX.InARMHeader).PutObject(pIOStream,pBatch.Header,0)
	If $$$ISERR(tStatus) Quit
	Set seqKey = ""
	For {
		Set tElement = pBatch.Record.GetNext(.seqKey)
		If (seqKey = "") Quit
		If $IsObject(tElement) {
			Set tStatus = tElement.PutSequence(pIOStream)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = pBatch.Record.%UnSwizzleAt(seqKey)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
	Do pIOStream.Flush(.tStatus)
	If $$$ISERR(tStatus) Quit
} Catch ex {
	Set tStatus = $$$SystemError
}
Quit tStatus

Set tStatus = $$$OK
Try {
	If '$IsObject(pIOStream) {
		Set tFilename = pIOStream
		Set pIOStream = ##class(%IO.FileStream).%New()
		Do pIOStream.Open(tFilename,,pTimeout,"UTF-8",.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	Set pIOStream.CharEncoding = "UTF-8"
	Set pBatch = ##class(IHC.ITF.BILLING.DStruc.ARMRefundToIDX.InARM.Batch).%New()
	Set pBatch.%Source = pIOStream.Name
	Set pLookAhead = $get(pLookAhead)
	Set tStatus = ##class(IHC.ITF.BILLING.DStruc.ARMRefundToIDX.InARMHeader).GetObject(pIOStream,.tHeader,pTimeout,.pLookAhead)
	If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"Header","IHC.ITF.BILLING.DStruc.ARMRefundToIDX.InARMHeader",$classname()),tStatus) Quit
	Set pBatch.Header = tHeader
	If (2 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(2-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"Record","IHC.ITF.BILLING.DStruc.ARMRefundToIDX.InARM.Record",$classname()),tStatus) Quit
	}
	Set tCount = 0
	While ($extract(pLookAhead,1,2)="00") {
		Set tStatus = ..getSeqRecord(pIOStream,.tSequence,.pLookAhead,pBatch,pTimeout)
		Set tCount = tCount + 1
		If $$$ISERR(tStatus) Quit
		Set tStatus = pBatch.Record.SetAt(tSequence,tCount)
		If $$$ISERR(tStatus) Quit
		If (2 > $length(pLookAhead)) {
			Set pLookAhead = pLookAhead _ pIOStream.Read(2-$length(pLookAhead),pTimeout,.tStatus)
			If $$$ISERR(tStatus) Quit
		}
	}
	If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexRepeating,"Record","IHC.ITF.BILLING.DStruc.ARMRefundToIDX.InARM.Record",$classname(),tCount),tStatus) Quit
} Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus

Set tStatus = $$$OK
Try {
	Set pSequence = ##class(IHC.ITF.BILLING.DStruc.ARMRefundToIDX.InARM.Record).%New()
	If (2 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(2-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,2) = "00") {
		Set tStatus = ##class(IHC.ITF.BILLING.DStruc.ARMRefundToIDX.InARMDetail).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"Detail","IHC.ITF.BILLING.DStruc.ARMRefundToIDX.InARMDetail",$classname()),tStatus) Quit
		Set pSequence.Detail = tObject
	}
}
Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus
